changeSet.sql:
CREATE TABLE notifications ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, recipient_profile_id BIGINT NOT NULL, sender_profile_id BIGINT, type TEXT NOT NULL CHECK (type IN ( 'like_post','like_comment','like_story', 'comment','comment_reply', 'follow','follow_request','follow_accepted', 'mention_post','mention_comment','mention_story', 'tag','message','story_view' )), reference_type TEXT CHECK (reference_type IS NULL OR reference_type IN ('post','comment','story','chat','profile')), reference_id BIGINT, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
CONSTRAINT NOTIFICATIONS_RECIPIENT_FK FOREIGN KEY (recipient_profile_id) REFERENCES profiles(id) ON DELETE CASCADE, CONSTRAINT NOTIFICATIONS_SENDER_FK FOREIGN KEY (sender_profile_id) REFERENCES profiles(id) ON DELETE SET NULL );
CREATE INDEX idx_notifications_recipient ON notifications(recipient_profile_id, created_at DESC); CREATE INDEX idx_notifications_unread ON notifications(recipient_profile_id, is_read) WHERE is_read = FALSE;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = 'notifications' AND column_name = 'id_uuid'
    ) THEN
        ALTER TABLE notifications ADD COLUMN id_uuid UUID DEFAULT uuid_generate_v7();
    END IF;
END $$;

UPDATE notifications
SET id_uuid = uuid_generate_v7()
WHERE id_uuid IS NULL;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.table_constraints
        WHERE table_name = 'notifications'
          AND constraint_name = 'notifications_id_uuid_key'
    ) THEN
        ALTER TABLE notifications ADD CONSTRAINT notifications_id_uuid_key UNIQUE (id_uuid);
    END IF;
END $$;

ALTER TABLE notifications DROP CONSTRAINT IF EXISTS notifications_pkey;
ALTER TABLE notifications RENAME COLUMN id TO id_legacy_tmp;
ALTER TABLE notifications RENAME COLUMN id_uuid TO id;
ALTER TABLE notifications ADD CONSTRAINT notifications_pkey PRIMARY KEY (id);
ALTER TABLE notifications ALTER COLUMN id SET DEFAULT uuid_generate_v7();
ALTER TABLE notifications DROP COLUMN id_legacy_tmp;

ALTER TABLE notifications DROP CONSTRAINT IF EXISTS notifications_type_check;
ALTER TABLE notifications
    ADD CONSTRAINT notifications_type_check
    CHECK (type IN (
        'like_post','like_comment','like_story',
        'comment','comment_reply',
        'follow','follow_request','follow_accepted',
        'mention_post','mention_comment','mention_story',
        'tag','message','story_view'
    ));

ALTER TABLE notifications DROP CONSTRAINT IF EXISTS notifications_reference_type_check;
ALTER TABLE notifications
    ADD CONSTRAINT notifications_reference_type_check
    CHECK (reference_type IS NULL OR reference_type IN ('post','comment','story','profile','message'));

ALTER TABLE notifications
    ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;

CREATE INDEX IF NOT EXISTS idx_notifications_deleted_at ON notifications(deleted_at);

